import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] buf = System.in.readAllBytes();
        int start = 0;
        while (buf[start] <= ' ') start++;
        int end = start;
        while (end < buf.length && buf[end] > ' ') end++;
        int n = end - start;
        int[] prefix = new int[n]; // KMP prefix function
        for (int i = 1, j = 0; i < n; i++) {
            while (j > 0 && buf[start + i] != buf[start + j]) j = prefix[j - 1];
            if (buf[start + i] == buf[start + j]) j++;
            prefix[i] = j;
        }
        System.out.println(prefix[n - 1]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

